"part": "B",
"prog": "String Surgery",
"should": "A program that takes a full name apart: first name, last name, initials and a school email address.",
"bad": "string space = text.IndexOf(\" \");",
"also": [],
"cs": {
"methods": "public static string FirstWord(string text)\n{\n    string space = text.IndexOf(\" \");\n    if (space == -1)\n    {\n        return text;\n    }\n    return text.Substring(0, space);\n}\n\npublic static string LastWord(string text)\n{\n    int space = text.IndexOf(\" \");\n    if (space == -1)\n    {\n        return text;\n    }\n    return text.Substring(space + 1);\n}\n\npublic static string Initials(string fullName)\n{\n    return FirstWord(fullName).Substring(0, 1) + LastWord(fullName).Substring(0, 1);\n}\n\npublic static string MakeEmail(string first, string last)\n{\n    string email = first.Substring(0, 1) + last;\n    email = email.ToLower();\n    email = email.Replace(\"'\", \"\");\n    email = email.Replace(\" \", \"\");\n    return email + \"@example.com\";\n}",
"main": "Console.Write(\"Type your full name: \");\nstring name = Console.ReadLine();\nConsole.WriteLine($\"First name: {FirstWord(name)}\");\nConsole.WriteLine($\"Last name: {LastWord(name)}\");\nConsole.WriteLine($\"Initials: {Initials(name)}\");\nConsole.WriteLine($\"Email: {MakeEmail(FirstWord(name), LastWord(name))}\");\nConsole.WriteLine($\"Starts with O': {LastWord(name).StartsWith(\"O'\")}\");\nConsole.WriteLine($\"Has a hyphen: {name.Contains(\"-\")}\");\nname = name.ToUpper();\nConsole.WriteLine(name);\nConsole.WriteLine();\nConsole.WriteLine(\"Press Enter to close this window.\");\nConsole.ReadLine();",
"stdin": "Aoife O'Neill\n\n"
},
"expect": {
"errors": [
"CS0019",
"CS0029",
"CS1503"
],
"msgs": [
[
"CS0029",
"Cannot implicitly convert type 'int' to 'string'"
],
[
"CS0019",
"Operator '==' cannot be applied to operands of type 'string' and 'int'"
],
[
"CS1503",
"Argument 2: cannot convert from 'string' to 'int'"
]
]
},
"fixes": [
{
"t": "int space = text.IndexOf(\" \");",
"ok": true,
"why": "Store the position of the first space in a new int called space."
},
{
"t": "int space = text.Length;",
"ok": false,
"why": "That is how long the text is, so the whole name comes back as the first word."
},
{
"t": "int space = text.Substring(\" \");",
"ok": false,
"why": "Substring takes numbers and gives text. IndexOf is the method that finds a position."
}
],
